-- Rook initial schema.
--
-- Conventions used throughout:
--
--   * Identifiers are UUIDv7, generated by the application rather than the
--     database. UUIDv7 sorts by creation time, which is what lets a message id
--     double as a pagination cursor and, later, as a partition key. Generating
--     them in the application keeps ids available before the insert (for
--     logging and for the outbox) and keeps the schema portable across
--     PostgreSQL versions that lack a built-in uuidv7().
--   * Timestamps are `timestamptz`, always stored in UTC.
--   * Text length limits mirror the Zod schemas in @rook/contracts. Both exist
--     on purpose: validation gives a good error message, the constraint
--     guarantees the invariant even if a future code path forgets to validate.
--   * Every foreign key states its delete behaviour explicitly, because the
--     default (NO ACTION) is rarely what is actually wanted.

-- ---------------------------------------------------------------------------
-- Users
-- ---------------------------------------------------------------------------

create table users (
  id               uuid primary key,

  -- Stored already lowercased by the application. A plain unique index is
  -- therefore sufficient and avoids depending on the citext extension.
  username         text        not null,
  email            text        not null,

  -- Argon2id PHC string. Contains its own salt and parameters, so the hash
  -- stays verifiable after the cost parameters are raised.
  password_hash    text        not null,

  display_name     text        not null,

  -- Set once the user uploads an avatar. The foreign key is added after
  -- media_assets exists, further down.
  avatar_asset_id  uuid,

  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),

  constraint users_username_length check (char_length(username) between 3 and 32),
  constraint users_username_format check (username ~ '^[a-z0-9._]+$'),
  constraint users_email_length check (char_length(email) between 3 and 254),
  constraint users_display_name_length check (char_length(display_name) between 1 and 64)
);

-- Case-insensitive uniqueness is achieved by storing the normalised form, so
-- these are plain unique indexes rather than expression indexes.
create unique index users_username_key on users (username);
create unique index users_email_key on users (email);

-- ---------------------------------------------------------------------------
-- Sessions
-- ---------------------------------------------------------------------------

create table sessions (
  id            uuid primary key,
  user_id       uuid        not null references users (id) on delete cascade,

  -- SHA-256 of (pepper || token). The raw token is never stored, so a stolen
  -- database dump does not yield usable session tokens without the pepper,
  -- which lives only in the environment.
  token_hash    bytea       not null,

  created_at    timestamptz not null default now(),
  expires_at    timestamptz not null,

  -- Updated at most once per minute by the API, to keep an active session
  -- from issuing a write on every request.
  last_seen_at  timestamptz not null default now(),

  -- Set on logout or administrative revocation. Kept rather than deleted so
  -- an audit trail survives; the cleanup job removes rows well after expiry.
  revoked_at    timestamptz,

  -- Truncated by the application. Purely diagnostic.
  user_agent    text,

  constraint sessions_expires_after_creation check (expires_at > created_at)
);

create unique index sessions_token_hash_key on sessions (token_hash);

-- "List and revoke my sessions", and cascade lookups by user.
create index sessions_user_id_idx on sessions (user_id);

-- Supports the expired-session cleanup job without scanning live sessions.
create index sessions_expires_at_idx on sessions (expires_at)
  where revoked_at is null;

-- ---------------------------------------------------------------------------
-- Communities and membership
-- ---------------------------------------------------------------------------

create table communities (
  id              uuid primary key,
  name            text        not null,

  -- Human-shareable join code. Invites are future work; this keeps the join
  -- flow real without pretending to be an access-control feature.
  join_code       text        not null,

  icon_asset_id   uuid,
  owner_id        uuid        not null references users (id) on delete restrict,

  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint communities_name_length check (char_length(name) between 2 and 64),
  constraint communities_join_code_length check (char_length(join_code) between 4 and 64)
);

create unique index communities_join_code_key on communities (join_code);
create index communities_owner_id_idx on communities (owner_id);

create table community_members (
  community_id  uuid        not null references communities (id) on delete cascade,
  user_id       uuid        not null references users (id) on delete cascade,

  role          text        not null default 'member',

  joined_at     timestamptz not null default now(),

  primary key (community_id, user_id),
  constraint community_members_role_valid check (role in ('owner', 'admin', 'member'))
);

-- "Which communities am I in?" — the query that runs on every app launch.
-- Without this index it is a sequential scan of every membership row in the
-- system.
create index community_members_user_id_idx on community_members (user_id, joined_at desc);

-- Member list pagination, ordered stably by (joined_at, user_id).
create index community_members_roster_idx
  on community_members (community_id, joined_at, user_id);

-- ---------------------------------------------------------------------------
-- Channels
-- ---------------------------------------------------------------------------

create table channels (
  id            uuid primary key,
  community_id  uuid        not null references communities (id) on delete cascade,

  -- Enum-as-text with a check constraint: adding 'voice' later is a one-line
  -- constraint change rather than a type migration that locks the table.
  kind          text        not null default 'text',

  name          text        not null,
  topic         text,
  position      integer     not null default 0,

  created_by    uuid        not null references users (id) on delete restrict,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint channels_kind_valid check (kind in ('text')),
  constraint channels_name_length check (char_length(name) between 1 and 64),
  constraint channels_name_format check (name ~ '^[a-z0-9-]+$'),
  constraint channels_topic_length check (topic is null or char_length(topic) <= 512),
  constraint channels_position_non_negative check (position >= 0)
);

-- Two #general channels in one community would be indistinguishable in the UI.
create unique index channels_community_name_key on channels (community_id, name);

-- Sidebar ordering for a community.
create index channels_community_position_idx on channels (community_id, position, id);

-- ---------------------------------------------------------------------------
-- Media assets
-- ---------------------------------------------------------------------------

create table media_assets (
  id                    uuid primary key,
  owner_id              uuid        not null references users (id) on delete restrict,

  -- reserved -> uploaded -> ready, or -> failed. Forward-only.
  status                text        not null default 'reserved',

  -- Derived from the asset id alone, never from the client's filename. A
  -- filename like '../../etc/passwd' therefore cannot influence where bytes
  -- are written.
  storage_key           text        not null,

  -- What the client claimed at authorisation time, kept for comparison
  -- against what was actually uploaded.
  declared_content_type text        not null,
  declared_byte_size    bigint      not null,

  -- Detected from the object's magic bytes after upload. Null until verified.
  content_type          text,
  byte_size             bigint,
  width                 integer,
  height                integer,

  -- Original filename, for display only. Never used to build a path.
  filename              text,

  -- Safe-to-display failure reason. Never contains storage keys or stack traces.
  failure_reason        text,

  -- Incremented by the worker. Lets a poisoned job be identified rather than
  -- retried forever.
  attempts              integer     not null default 0,

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  confirmed_at          timestamptz,
  processed_at          timestamptz,

  constraint media_assets_status_valid
    check (status in ('reserved', 'uploaded', 'ready', 'failed')),
  constraint media_assets_declared_size_positive check (declared_byte_size > 0),
  constraint media_assets_byte_size_non_negative check (byte_size is null or byte_size >= 0),
  constraint media_assets_dimensions_positive
    check ((width is null or width > 0) and (height is null or height > 0)),
  constraint media_assets_failure_reason_length
    check (failure_reason is null or char_length(failure_reason) <= 256),

  -- A ready asset must have been verified. Enforced in the schema because a
  -- 'ready' asset with no content type would break every consumer.
  constraint media_assets_ready_is_verified
    check (status <> 'ready' or (content_type is not null and byte_size is not null))
);

create index media_assets_owner_idx on media_assets (owner_id, created_at desc);

-- Drives the orphaned-upload sweeper: reservations the client never confirmed.
create index media_assets_reserved_idx on media_assets (created_at)
  where status = 'reserved';

-- Lets the worker find assets awaiting processing after a restart, so work is
-- recovered from the database rather than lost with the queue.
create index media_assets_pending_processing_idx on media_assets (confirmed_at)
  where status = 'uploaded';

create table media_variants (
  asset_id      uuid        not null references media_assets (id) on delete cascade,
  name          text        not null,

  storage_key   text        not null,
  content_type  text        not null,
  width         integer     not null,
  height        integer     not null,
  byte_size     bigint      not null,

  created_at    timestamptz not null default now(),

  primary key (asset_id, name),
  constraint media_variants_name_valid check (name in ('thumbnail', 'preview', 'original')),
  constraint media_variants_dimensions_positive check (width > 0 and height > 0),
  constraint media_variants_byte_size_non_negative check (byte_size >= 0)
);

-- Deferred foreign keys for avatars and icons, now that media_assets exists.
-- Clearing the asset rather than the user is the right behaviour here, so both
-- are ON DELETE SET NULL.
alter table users
  add constraint users_avatar_asset_fk
  foreign key (avatar_asset_id) references media_assets (id) on delete set null;

alter table communities
  add constraint communities_icon_asset_fk
  foreign key (icon_asset_id) references media_assets (id) on delete set null;

-- ---------------------------------------------------------------------------
-- Messages
-- ---------------------------------------------------------------------------

create table messages (
  -- UUIDv7: monotonic by creation time, so (channel_id, id) ordering is
  -- chronological and the id works directly as a cursor.
  id               uuid        primary key,
  channel_id       uuid        not null references channels (id) on delete cascade,

  -- RESTRICT, not CASCADE: deleting a user must not silently erase their side
  -- of every conversation. Account deletion needs an anonymisation strategy
  -- and is documented as future work.
  author_id        uuid        not null references users (id) on delete restrict,

  -- Null once deleted. The row is kept as a tombstone so clients already
  -- displaying the message are told it is gone, and so cursor pagination
  -- stays consistent.
  content          text,

  -- Client-generated, making a retry after a timeout idempotent.
  idempotency_key  uuid        not null,

  created_at       timestamptz not null default now(),
  edited_at        timestamptz,
  deleted_at       timestamptz,

  constraint messages_content_length
    check (content is null or char_length(content) <= 4000),

  -- A live message must have content; a deleted one must not.
  constraint messages_content_matches_state
    check ((deleted_at is null and content is not null) or deleted_at is not null),

  constraint messages_edited_after_created
    check (edited_at is null or edited_at >= created_at)
);

-- The index that makes history loading cheap: a backwards index scan over one
-- channel, seeking straight to the cursor. Serves both "latest N" and
-- "N before cursor" with no sort step.
create index messages_channel_id_desc_idx on messages (channel_id, id desc);

-- Enforces send idempotency. Scoped per author so two users cannot collide on
-- a key, and so a replayed request from one client resolves to its own row.
create unique index messages_idempotency_key
  on messages (channel_id, author_id, idempotency_key);

-- Supports "messages by this author", used by moderation tooling later.
create index messages_author_idx on messages (author_id, id desc);

create table message_attachments (
  message_id  uuid    not null references messages (id) on delete cascade,

  -- RESTRICT: an asset referenced by a message must not vanish from under it.
  asset_id    uuid    not null references media_assets (id) on delete restrict,

  -- Preserves the order the user attached them in.
  position    integer not null default 0,

  primary key (message_id, asset_id),
  constraint message_attachments_position_non_negative check (position >= 0)
);

-- Reverse lookup: "is this asset still referenced?", used before deletion.
create index message_attachments_asset_idx on message_attachments (asset_id);

-- ---------------------------------------------------------------------------
-- Transactional outbox
-- ---------------------------------------------------------------------------
--
-- Rows are inserted in the same transaction as the change they describe, so a
-- committed change always has its event and a rolled-back one never does.
-- A relay process publishes unpublished rows to Redis and marks them done.
--
-- This is what prevents the classic failure: write to Postgres, then crash
-- before publishing, leaving connected clients permanently out of sync with
-- durable state.

create table event_outbox (
  id              uuid        primary key,

  event_type      text        not null,

  -- Pre-resolved delivery audience, so a gateway never has to query Postgres
  -- to decide who receives an event.
  audience_scope  text        not null,
  audience_id     uuid        not null,

  -- Suppressed on this user's own connections: they already applied the
  -- change optimistically, and echoing it back causes a visible flicker.
  origin_user_id  uuid,

  -- The exact client-facing event, already validated against its schema.
  payload         jsonb       not null,

  occurred_at     timestamptz not null default now(),
  published_at    timestamptz,
  attempts        integer     not null default 0,

  constraint event_outbox_audience_scope_valid
    check (audience_scope in ('channel', 'community', 'user'))
);

-- The relay's only read path. Partial, so it holds just the backlog: once a
-- row is published it leaves the index, which keeps it tiny regardless of how
-- many events have been processed historically.
create index event_outbox_unpublished_idx on event_outbox (id)
  where published_at is null;

-- Supports pruning published rows after the retention window.
create index event_outbox_published_at_idx on event_outbox (published_at)
  where published_at is not null;
